package com.mapmates.moderation;
import com.mapmates.common.db.*;import com.mapmates.common.web.Validator;import com.mapmates.common.exception.ApiException;import com.mapmates.common.security.*;import java.sql.*;import java.util.*;
public final class SafetyService {
 public record Report(String targetType,Long targetId,String reason){}
 public record Review(String status,String note){}
 public static void interaction(Connection c,long a,long b)throws SQLException {if(a!=b&&Sql.one(c,"SELECT 1 FROM member_blocks WHERE (blocker_id=? AND blocked_id=?) OR (blocker_id=? AND blocked_id=?)",a,b,b,a)!=null)throw ApiException.forbidden("차단 관계인 회원과 새로 상호작용할 수 없어요.");}
 public Object blocks(long user){return Tx.read(c->Sql.rows(c,"SELECT CAST(m.id AS CHAR) AS id,m.nickname,b.created_at AS createdAt FROM member_blocks b JOIN members m ON m.id=b.blocked_id WHERE b.blocker_id=? ORDER BY b.created_at DESC",user));}
 public void block(long user,long target,boolean block){if(user==target)throw ApiException.badRequest("자신을 차단할 수 없어요.");Tx.write(c->{if(Sql.one(c,"SELECT id FROM members WHERE id=?",target)==null)throw ApiException.notFound("회원을 찾을 수 없어요.");if(block)Sql.update(c,"INSERT INTO member_blocks(blocker_id,blocked_id) VALUES(?,?) ON DUPLICATE KEY UPDATE blocker_id=VALUES(blocker_id)",user,target);else Sql.update(c,"DELETE FROM member_blocks WHERE blocker_id=? AND blocked_id=?",user,target);return null;});}
 public Object report(long user,Report request){RequestLimits.check("report:"+user,10,3600000);String type=Validator.requireOneOf(request.targetType(),"신고 대상","member","post","comment","companion"),reason=Validator.requireText(request.reason(),500,"신고 사유");if(request.targetId()==null||request.targetId()<=0)throw ApiException.badRequest("신고 대상을 확인해주세요.");return Tx.write(c->{String sql=switch(type){case "member"->"SELECT id AS owner,nickname AS label FROM members WHERE id=?";case "post"->"SELECT owner_id AS owner,title AS label FROM posts WHERE id=?";case "comment"->"SELECT owner_id AS owner,content AS label FROM comments WHERE id=?";default->"SELECT p.owner_id AS owner,p.title AS label FROM companions cp JOIN plans p ON p.id=cp.plan_id WHERE cp.id=?";};var target=Sql.one(c,sql,request.targetId());if(target==null)throw ApiException.notFound("신고 대상을 찾을 수 없어요.");if(Sql.number(target,"owner")==user)throw ApiException.badRequest("본인 콘텐츠는 신고할 수 없어요.");String label=Objects.toString(target.get("label"),"");label=label.substring(0,label.offsetByCodePoints(0,Math.min(200,label.codePointCount(0,label.length()))));long id;try{id=Sql.insert(c,"INSERT INTO reports(reporter_id,target_type,target_id,target_label,reason) VALUES(?,?,?,?,?)",user,type,request.targetId(),label,reason);}catch(SQLIntegrityConstraintViolationException e){throw ApiException.conflict("이미 신고한 대상이에요.");}return Map.of("id",id,"status","open");});}
 public Object mine(long user){return Tx.read(c->Sql.rows(c,"SELECT id,target_type AS targetType,target_label AS targetLabel,status,reason,review_note AS reviewNote,created_at AS createdAt FROM reports WHERE reporter_id=? ORDER BY id DESC LIMIT 100",user));}
 public Object list(SessionUser admin,String status,int page,int size){admin(admin);String valid=status==null?"open":Validator.requireOneOf(status,"처리 상태","open","reviewed","dismissed");return Tx.read(c->Map.of("items",Sql.rows(c,"SELECT id,target_type AS targetType,target_id AS targetId,target_label AS targetLabel,reason,status,review_note AS reviewNote,reviewer_id AS reviewerId,created_at AS createdAt,reviewed_at AS reviewedAt FROM reports WHERE status=? ORDER BY id DESC LIMIT ? OFFSET ?",valid,size,(page-1)*size),"total",Sql.number(Sql.one(c,"SELECT COUNT(*) n FROM reports WHERE status=?",valid),"n"),"page",page,"size",size));}
 public void review(long id,SessionUser admin,Review request){admin(admin);String status=Validator.requireOneOf(request.status(),"검토 결과","reviewed","dismissed"),note=Validator.requireText(request.note(),500,"처리 기록");Tx.write(c->{var r=Sql.one(c,"SELECT status FROM reports WHERE id=? FOR UPDATE",id);if(r==null)throw ApiException.notFound("신고를 찾을 수 없어요.");if(!"open".equals(r.get("status")))throw ApiException.conflict("이미 처리한 신고예요.");return Sql.update(c,"UPDATE reports SET status=?,reviewer_id=?,review_note=?,reviewed_at=NOW() WHERE id=?",status,admin.id(),note,id);});}
 private void admin(SessionUser user){if(!user.isAdmin())throw ApiException.forbidden("운영자만 확인할 수 있어요.");}
}
